import { useEffect, useRef, useState } from "react";
import { prefersReducedMotion, readDurationMs } from "../lib/motion";

const ATTACH_THRESHOLD = 24;
const GLIDE_LIMIT = 240;

type ScrollAnchor = { element: HTMLElement; offset: number };

function firstVisibleChild(list: HTMLElement, scrollTop: number) {
  const children = list.children;
  let low = 0;
  let high = children.length - 1;
  let found: HTMLElement | undefined;
  while (low <= high) {
    const middle = (low + high) >> 1;
    const child = children[middle];
    if (child instanceof HTMLElement && child.offsetTop + child.offsetHeight > scrollTop) {
      found = child;
      high = middle - 1;
    } else {
      low = middle + 1;
    }
  }
  return found;
}

function distanceToEnd(viewport: HTMLElement) {
  return viewport.scrollHeight - viewport.clientHeight - viewport.scrollTop;
}

export function useChatThreadScroll() {
  const rootRef = useRef<HTMLDivElement>(null);
  const viewportRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const dockRef = useRef<HTMLDivElement>(null);
  const followingRef = useRef(true);
  const travellingRef = useRef(false);
  const [atBottom, setAtBottom] = useState(true);

  function scrollToBottom(behavior?: ScrollBehavior) {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const resolved = behavior ?? (prefersReducedMotion(viewport) ? "auto" : "smooth");
    followingRef.current = true;
    travellingRef.current = resolved === "smooth";
    setAtBottom(true);
    viewport.scrollTo({ top: viewport.scrollHeight, behavior: resolved });
  }

  function followFromDock() {
    if (!followingRef.current) scrollToBottom();
  }

  useEffect(() => {
    const viewport = viewportRef.current;
    const content = contentRef.current;
    const messageList = content?.firstElementChild;
    if (!viewport || !content || !(messageList instanceof HTMLElement)) return;
    let anchor: ScrollAnchor | undefined;
    let lastTop = viewport.scrollTop;
    let settled = false;

    const rememberAnchor = () => {
      const element = firstVisibleChild(messageList, viewport.scrollTop);
      anchor = element ? { element, offset: element.offsetTop - viewport.scrollTop } : undefined;
    };

    // Browsers skip native scroll anchoring at offset 0, exactly where older history loads in.
    const keepAnchorInPlace = () => {
      if (!anchor?.element.isConnected) return;
      const drift = anchor.element.offsetTop - viewport.scrollTop - anchor.offset;
      if (drift !== 0) viewport.scrollTop += drift;
    };

    // Streamed lines land instantly at the end; the list slides up from where it was so reading never jumps.
    const glide = (distance: number) => {
      if (!settled || distance <= 0 || distance > GLIDE_LIMIT || prefersReducedMotion(messageList)) return;
      const duration = readDurationMs(messageList, "--duration-base");
      if (duration <= 0) return;
      messageList.animate([{ translate: `0 ${distance}px` }, { translate: "0 0" }], {
        duration,
        easing: getComputedStyle(messageList).getPropertyValue("--ease-emphasized").trim() || "ease-out",
        composite: "add",
      });
    };

    const followEnd = () => {
      if (travellingRef.current) {
        viewport.scrollTo({ top: viewport.scrollHeight, behavior: "smooth" });
        return;
      }
      const before = viewport.scrollTop;
      viewport.scrollTop = viewport.scrollHeight;
      glide(viewport.scrollTop - before);
    };

    // Only the reader moves the thread up: growth below never lowers scrollTop, and a shrink clamps it flush with the end.
    const handleScroll = () => {
      const top = viewport.scrollTop;
      const remaining = distanceToEnd(viewport);
      if (top < lastTop && remaining > 1) {
        followingRef.current = false;
        travellingRef.current = false;
      } else if (remaining <= ATTACH_THRESHOLD) {
        followingRef.current = true;
      }
      if (remaining <= 1) travellingRef.current = false;
      lastTop = top;
      rememberAnchor();
      setAtBottom(followingRef.current || remaining <= ATTACH_THRESHOLD);
    };

    const handleResize = () => {
      rootRef.current?.style.setProperty("--_chat-thread-dock-size", `${dockRef.current?.offsetHeight ?? 0}px`);
      if (followingRef.current) followEnd();
      else keepAnchorInPlace();
      lastTop = viewport.scrollTop;
      rememberAnchor();
      setAtBottom(followingRef.current || distanceToEnd(viewport) <= ATTACH_THRESHOLD);
    };

    const settleTravel = () => {
      travellingRef.current = false;
    };

    const observer = new ResizeObserver(handleResize);
    observer.observe(content);
    observer.observe(viewport);
    if (dockRef.current) observer.observe(dockRef.current);
    viewport.addEventListener("scroll", handleScroll, { passive: true });
    viewport.addEventListener("scrollend", settleTravel);
    handleResize();
    settled = true;
    content.setAttribute("data-settled", "");

    return () => {
      observer.disconnect();
      viewport.removeEventListener("scroll", handleScroll);
      viewport.removeEventListener("scrollend", settleTravel);
      content.removeAttribute("data-settled");
    };
  }, []);

  return { rootRef, viewportRef, contentRef, dockRef, atBottom, scrollToBottom, followFromDock };
}

"use client";

import { useRender } from "@base-ui/react/use-render";
import { ArrowDown } from "lucide-react";
import type { ComponentProps, CSSProperties, MouseEvent, ReactNode, RefObject } from "react";
import { createContext, useContext, useState } from "react";
import { createPortal } from "react-dom";
import type { RenderProp } from "@/components/control-ui/control-props";
import { ChatThreadAnnounceContext, ChatThreadDockContext } from "@/components/control-ui/hooks/use-chat-message";
import { useChatThreadScroll } from "@/components/control-ui/hooks/use-chat-thread-scroll";
import type { ChatLayoutKnobStyle } from "@/components/control-ui/knob-contracts/chat-layout-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { SkinAdornment } from "@/components/control-ui/skin-provider";
import { Button } from "@/components/control-ui/ui/button";
import { LiveStatus } from "@/components/control-ui/ui/live-status";
import { ScrollArea } from "@/components/control-ui/ui/scroll-area";

export type ChatLayoutChrome = "panel" | "embedded";

export type ChatLayoutProps = Omit<ComponentProps<"section">, "style"> & {
  chrome?: ChatLayoutChrome;
  style?: CSSProperties & ChatLayoutKnobStyle;
};

const chromeSizing: Record<ChatLayoutChrome, string> = {
  panel: "mx-auto min-h-[640px] max-w-3xl",
  embedded: "h-full min-h-0 flex-1",
};

export function ChatLayout({ children, chrome = "panel", className, ...props }: ChatLayoutProps) {
  return (
    <section
      data-control-ui="chat-layout"
      data-control-family="chat-layout"
      data-slot="root"
      data-chrome={chrome}
      data-surface={chrome === "panel" ? "panel" : undefined}
      className={cn("relative flex w-full flex-col overflow-hidden", chromeSizing[chrome], className)}
      {...props}
    >
      {chrome === "panel" ? <SkinAdornment scope="chat-layout" part="titlebar" context={{}} /> : null}
      {children}
    </section>
  );
}

export type ChatLayoutHeaderProps = Omit<ComponentProps<"header">, "style"> & { style?: CSSProperties & ChatLayoutKnobStyle };

export function ChatLayoutHeader({ className, ...props }: ChatLayoutHeaderProps) {
  return (
    <header
      data-control-ui="chat-layout"
      data-control-family="chat-layout"
      data-slot="header"
      className={cn("grid shrink-0 grid-cols-[auto_minmax(0,1fr)_auto] items-center", className)}
      {...props}
    />
  );
}

export type ChatLayoutTitleProps = Omit<ComponentProps<"div">, "style"> & {
  render?: RenderProp<ComponentProps<"div">>;
  style?: CSSProperties & ChatLayoutKnobStyle;
};

/** Renders a `div`; pass `render={(props) => <h2 {...props} />}` for the heading level the page needs. */
export function ChatLayoutTitle({ render, className, ...props }: ChatLayoutTitleProps) {
  return useRender({
    defaultTagName: "div",
    render,
    props: {
      ...props,
      className: cn("col-start-2 min-w-0 truncate", className),
      "data-control-ui": "chat-layout",
      "data-control-family": "chat-layout",
      "data-slot": "title",
    },
  });
}

export type ChatLayoutDescriptionProps = Omit<ComponentProps<"p">, "style"> & { style?: CSSProperties & ChatLayoutKnobStyle };

export function ChatLayoutDescription({ className, ...props }: ChatLayoutDescriptionProps) {
  return (
    <p
      data-control-ui="chat-layout"
      data-control-family="chat-layout"
      data-slot="description"
      className={cn("col-start-2 truncate", className)}
      {...props}
    />
  );
}

export type ChatLayoutActionsProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & ChatLayoutKnobStyle };

export function ChatLayoutActions({ className, ...props }: ChatLayoutActionsProps) {
  return (
    <div
      data-control-ui="chat-layout"
      data-control-family="chat-layout"
      data-slot="actions"
      className={cn("col-start-3 row-span-2 row-start-1 flex items-center", className)}
      {...props}
    />
  );
}

type ChatThreadScrollContextValue = {
  atBottom: boolean;
  scrollToBottom: (behavior?: ScrollBehavior) => void;
  viewportRef: RefObject<HTMLDivElement | null>;
  anchorLayer: HTMLDivElement | null;
};

const ChatThreadScrollContext = createContext<ChatThreadScrollContextValue | null>(null);

/** Scroll state of the surrounding `ChatThread`, for a custom jump control or an unread marker. */
export function useChatThread(): Pick<ChatThreadScrollContextValue, "atBottom" | "scrollToBottom"> {
  const scroll = useContext(ChatThreadScrollContext);
  if (!scroll) throw new Error("useChatThread() must be called inside <ChatThread>.");
  return { atBottom: scroll.atBottom, scrollToBottom: scroll.scrollToBottom };
}

export type ChatThreadProps = ComponentProps<"div"> & {
  composer?: ReactNode;
};

export function ChatThread({
  children,
  composer,
  className,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledby,
  ...props
}: ChatThreadProps) {
  const { rootRef, viewportRef, contentRef, dockRef, atBottom, scrollToBottom, followFromDock } = useChatThreadScroll();
  const [anchorLayer, setAnchorLayer] = useState<HTMLDivElement | null>(null);
  const [announcement, setAnnouncement] = useState("");
  const [announce] = useState(() => (message: string) => {
    // A trailing no-break space makes a repeated message a real text change, so it is read again.
    setAnnouncement((current) => (current === message ? `${message}\u00a0` : message));
  });

  return (
    <ChatThreadAnnounceContext.Provider value={announce}>
      <ChatThreadScrollContext.Provider value={{ atBottom, scrollToBottom, viewportRef, anchorLayer }}>
        <div
          ref={rootRef}
          data-control-ui="chat-thread"
          data-control-family="chat-layout"
          data-chat-layout-kind="thread"
          data-slot="root"
          data-at-bottom={atBottom ? "" : undefined}
          className={cn("relative flex min-h-0 min-w-0 flex-1 flex-col", className)}
          {...props}
        >
          {/* The viewport is the focusable scroller, so a name belongs there (as a region), not on the role-less root. */}
          <ScrollArea
            aria-label={ariaLabel ?? (ariaLabelledby ? undefined : "Conversation")}
            aria-labelledby={ariaLabelledby}
            className="min-h-0 flex-1"
            contentClassName="flex min-h-full flex-col"
            viewportRef={viewportRef}
            lockAxis="x"
            blur={false}
          >
            <div
              ref={contentRef}
              data-control-ui="chat-thread"
              data-control-family="chat-layout"
              data-slot="track"
              className="relative flex min-w-0 flex-1 flex-col"
            >
              <div data-control-ui="chat-thread" data-control-family="chat-layout" data-slot="thread-content">
                {children}
              </div>
              {composer ? (
                <div
                  ref={dockRef}
                  data-control-ui="chat-thread"
                  data-control-family="chat-layout"
                  data-slot="dock"
                  data-scroll-area-pinned=""
                  className="sticky bottom-0 z-1 shrink-0"
                >
                  <ChatThreadDockContext.Provider value={followFromDock}>{composer}</ChatThreadDockContext.Provider>
                </div>
              ) : null}
            </div>
          </ScrollArea>
          <div ref={setAnchorLayer} data-control-ui="chat-thread" data-control-family="chat-layout" data-slot="anchor-layer" />
          <LiveStatus message={announcement} />
        </div>
      </ChatThreadScrollContext.Provider>
    </ChatThreadAnnounceContext.Provider>
  );
}

export type ChatThreadScrollButtonProps = Omit<ComponentProps<typeof Button>, "children"> & {
  label?: string;
};

export function ChatThreadScrollButton({
  label = "Scroll to latest",
  variant = "surface",
  size = "sm",
  shape = "circle",
  onClick,
  ...props
}: ChatThreadScrollButtonProps) {
  const scroll = useContext(ChatThreadScrollContext);
  if (!scroll) throw new Error("<ChatThreadScrollButton> must be rendered inside <ChatThread>.");

  function handleClick(event: MouseEvent<HTMLButtonElement>) {
    onClick?.(event);
    if (event.defaultPrevented || !scroll) return;
    scroll.scrollToBottom();
    // The button hides once the thread is at the bottom; hand its focus to the scroller instead of dropping it on <body>.
    if (document.activeElement === event.currentTarget) scroll.viewportRef.current?.focus({ preventScroll: true });
  }

  if (!scroll.anchorLayer) return null;
  return createPortal(
    <div
      data-control-ui="chat-thread"
      data-control-family="chat-layout"
      data-slot="scroll-anchor"
      data-hidden={scroll.atBottom ? "" : undefined}
    >
      <Button {...props} type="button" variant={variant} size={size} shape={shape} iconOnly aria-label={label} onClick={handleClick}>
        <ArrowDown aria-hidden="true" />
      </Button>
    </div>,
    scroll.anchorLayer,
  );
}

export type ChatTurnProps = ComponentProps<"section"> & {
  from: "user" | "assistant";
};

export function ChatTurn({ from, children, className, ...props }: ChatTurnProps) {
  return (
    <section
      data-control-ui="chat-turn"
      data-control-family="chat-layout"
      data-slot="turn"
      data-from={from}
      className={cn("flex w-full flex-col", from === "user" && "items-end", className)}
      {...props}
    >
      {children}
    </section>
  );
}

@layer components {
  :where([data-control-family="chat-layout"][data-slot="root"][data-chrome]) {
    --cui-chat-layout-radius: var(--radius-scene);
    --cui-chat-layout-background: var(--background);
    --cui-chat-layout-border-color: var(--border);
    --cui-chat-layout-border-width: var(--control-rim-width);
    --cui-chat-layout-shadow: var(--shadow-md);
    --cui-chat-layout-gutter-size: calc(var(--spacing) * 4);
    --cui-chat-layout-column-max-inline-size: 48rem;
    --cui-chat-layout-veil-background: var(--cui-chat-layout-background);
    --cui-chat-layout-veil-backdrop-filter: none;
    --cui-chat-layout-scroll-button-gap: calc(var(--spacing) * 3);
    --cui-chat-layout-turn-gap: calc(var(--spacing) * 2);
    container: chat-layout / inline-size;
  }

  :where(
    [data-control-family="chat-layout"][data-slot="root"][data-chrome="panel"]:has([data-control-family="chat-layout"][data-slot="dock"])
  ) {
    --cui-chat-layout-radius: max(
      var(--radius-scene),
      calc(var(--radius-composer) + var(--composer-padding) + var(--cui-chat-layout-border-width))
    );
  }

  :where([data-control-family="chat-layout"][data-slot="root"][data-chrome="panel"]) {
    background: var(--cui-chat-layout-background);
    border: var(--cui-chat-layout-border-width) solid var(--cui-chat-layout-border-color);
    border-radius: var(--cui-chat-layout-radius);
    box-shadow: var(--cui-chat-layout-shadow);
  }

  :where([data-popup-part="surface"] [data-control-family="chat-layout"][data-slot="root"][data-chrome="embedded"]) {
    --cui-chat-layout-background: var(--cui-popup-background);
    --cui-chat-layout-radius: var(--cui-popup-radius);
    border-radius: var(--cui-chat-layout-radius);
  }

  :where(
    [data-control-family="chat-workspace"][data-slot="panel"] [data-control-family="chat-layout"][data-slot="root"][data-chrome="embedded"]
  ) {
    --cui-chat-layout-background: var(--cui-chat-workspace-background);
    --cui-chat-layout-gutter-size: calc(var(--composer-padding) * 2 + var(--control-rim-width));
  }

  :where([data-control-family="chat-layout"][data-slot="header"]) {
    padding-block: calc(var(--spacing) * 3);
    padding-inline: var(--cui-chat-layout-gutter-size);
    border-block-end: var(--cui-chat-layout-border-width) solid var(--cui-chat-layout-border-color);
  }

  :where([data-control-family="chat-workspace"][data-slot="panel"] [data-control-family="chat-layout"][data-slot="header"]) {
    padding-block: calc(var(--spacing) * 2);
  }

  :where(
    [data-control-family="chat-workspace"][data-slot="root"]:not([data-docked])
      > [data-slot="panel"]
      [data-control-family="chat-layout"][data-slot="header"]
  ) {
    border-block-end-width: 0;
  }

  :where([data-control-family="chat-layout"][data-slot="header"] > :not([data-control-family="chat-layout"])) {
    grid-column: 1;
    grid-row: 1 / span 2;
    margin-inline-end: calc(var(--spacing) * 2);
  }

  :where([data-control-family="chat-layout"][data-slot="title"]) {
    font-size: var(--text-body);
    font-weight: var(--font-weight-semibold);
    line-height: var(--leading-tight);
    color: var(--foreground);
  }

  :where([data-control-family="chat-layout"][data-slot="title"]:not(:has(+ [data-control-family="chat-layout"][data-slot="description"]))) {
    grid-row: 1 / span 2;
  }

  :where([data-control-family="chat-layout"][data-slot="description"]) {
    margin-block-start: calc(var(--spacing) * 0.5);
    font-size: var(--text-caption);
    color: var(--muted-foreground);
  }

  :where([data-control-family="chat-layout"][data-slot="actions"]) {
    gap: calc(var(--spacing) * 1);
    margin-inline-start: calc(var(--spacing) * 3);
  }

  :where([data-control-family="chat-layout"][data-chat-layout-kind="thread"][data-slot="root"] > [data-control-family="scroll-area"]) {
    --_chat-thread-dock-size: inherit;
    --scroll-area-inset-end: var(--_chat-thread-dock-size);
    display: flex;
    flex-direction: column;
  }

  :where(
    [data-control-family="chat-layout"][data-chat-layout-kind="thread"][data-slot="root"]
      > [data-control-family="scroll-area"]
      > [data-scroll-area-viewport]
  ) {
    flex: 1 1 auto;
    min-block-size: 0;
    scroll-padding-block: var(--scroll-fade-size) calc(var(--scroll-area-inset-end) + var(--scroll-fade-size));
  }

  :where([data-control-family="chat-layout"][data-slot="track"]) {
    --_chat-layout-column-inset: max(var(--cui-chat-layout-gutter-size), calc((100% - var(--cui-chat-layout-column-max-inline-size)) / 2));
  }

  :where(
    [data-control-family="chat-layout"][data-slot="track"]:has(
      > [data-slot="thread-content"] > [data-control-family="chat-message"][data-layout="flat"]
    )
  ) {
    --_chat-layout-column-inset: var(--cui-chat-layout-gutter-size);
  }

  :where([data-control-family="chat-layout"][data-slot="thread-content"]) {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    min-inline-size: 0;
    gap: calc(var(--spacing) * 8);
    padding-block: calc(var(--spacing) * 6);
    padding-inline: var(--_chat-layout-column-inset);
  }

  :where([data-control-family="chat-layout"][data-slot="thread-content"]:has(> [data-control-family="chat-message"][data-layout="flat"])) {
    gap: 0;
  }

  :where(
    [data-control-family="chat-workspace"][data-slot="root"]:not([data-expanded], [data-folding])
      [data-control-family="chat-layout"][data-slot="thread-content"]:has(> [data-control-family="chat-workspace"][data-slot="collapsible"])
  ) {
    display: none;
  }

  :where([data-control-family="chat-layout"][data-slot="turn"]) {
    gap: var(--cui-chat-layout-turn-gap);
  }

  :where([data-control-family="chat-layout"][data-slot="dock"]) {
    padding-inline: var(--_chat-layout-column-inset);
    padding-block-end: env(safe-area-inset-bottom, 0px);
    background: var(--cui-chat-layout-veil-background);
    backdrop-filter: var(--cui-chat-layout-veil-backdrop-filter);
    transition:
      background-color var(--duration-fast) var(--ease-standard),
      backdrop-filter var(--duration-fast) var(--ease-standard);
  }

  :where([data-scroll-area-viewport]:not([data-overflow-y-end]) [data-control-family="chat-layout"][data-slot="dock"]) {
    background-color: transparent;
    backdrop-filter: none;
  }

  :where([data-control-family="chat-layout"][data-slot="anchor-layer"]) {
    --_chat-thread-dock-size: inherit;
    position: absolute;
    inset-inline: 0;
    inset-block-end: var(--_chat-thread-dock-size);
    z-index: 1;
    pointer-events: none;
  }

  :where([data-control-family="chat-layout"][data-slot="dock"]:has([data-control-family="chat-composer"][data-slot="root"])) {
    padding-inline: max(0px, calc(var(--_chat-layout-column-inset) - var(--composer-padding)));
  }

  :where(
    [data-control-family="chat-workspace"][data-slot="panel"]
      [data-control-family="chat-layout"][data-slot="dock"]:has([data-control-family="chat-composer"][data-slot="root"])
  ) {
    padding-inline: max(0px, calc(var(--_chat-layout-column-inset) - var(--cui-chat-layout-gutter-size)));
  }

  :where(
    [data-control-family="chat-workspace"][data-slot="root"]:not([data-docked])
      [data-control-family="chat-workspace"][data-slot="panel"]
      [data-control-family="chat-layout"][data-slot="dock"]
  ) {
    --nest-radius: max(0px, calc(var(--cui-chat-workspace-radius) - var(--cui-chat-workspace-border-width) - var(--composer-padding)));
  }

  :where(
    :is([data-popup-part="surface"], [data-control-family="chat-layout"][data-slot="root"][data-chrome="panel"])
      [data-control-family="chat-layout"][data-slot="dock"]
  ) {
    padding-block-end: 0;
  }

  :where([data-control-family="chat-layout"][data-slot="scroll-anchor"]) {
    position: absolute;
    inset-block-end: var(--cui-chat-layout-scroll-button-gap);
    pointer-events: auto;
    inset-inline: 0;
    margin-inline: auto;
    inline-size: fit-content;
    transition-property: opacity, scale, translate, visibility;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="chat-layout"][data-slot="scroll-anchor"][data-hidden]) {
    opacity: 0;
    scale: 0.92;
    translate: 0 calc(var(--spacing) * 2);
    visibility: hidden;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }
}

@property --cui-chat-layout-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-chat-layout-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-chat-layout-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-chat-layout-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-chat-layout-shadow {
  syntax: "*";
  inherits: true;
}

@property --cui-chat-layout-gutter-size {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-chat-layout-column-max-inline-size {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-chat-layout-veil-background {
  syntax: "<color>";
  inherits: true;
